package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;

public class TarUtils_formatUnsignedOctalString_TriageGen2Test {







    @Test
    public void testFormatUnsignedOctalString_ExactFit() {
        byte[] buffer = new byte[3];
        // 63 in octal is 77. Length 3 -> "077"
        // Wait, 63 decimal is 77 octal. To fit 77 in 3 chars, it becomes "077"
        TarUtils.formatUnsignedOctalString(63L, buffer, 0, 3);
        byte[] expected = "077".getBytes();
        assertArrayEquals(expected, buffer);
    }








}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;

public class TarUtils_formatUnsignedOctalString_TriageGen2Test {









    @Test(expected = IllegalArgumentException.class)
    public void testFormatUnsignedOctalString_Overflow() {
        byte[] buffer = new byte[2];
        // 100 decimal is 144 octal. Length 2 cannot fit "144"
        TarUtils.formatUnsignedOctalString(100L, buffer, 0, 2);
    }






}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;

public class TarUtils_formatUnsignedOctalString_TriageGen2Test {











    @Test
    public void testFormatUnsignedOctalString_WithOffset() {
        byte[] buffer = new byte[10];
        // Value 5, length 3, offset 2. Buffer: [0,0, '0','0','5', 0,0,0,0,0]
        TarUtils.formatUnsignedOctalString(5L, buffer, 2, 3);
        byte[] expected = {0, 0, '0', '0', '5', 0, 0, 0, 0, 0};
        assertArrayEquals(expected, buffer);
    }




}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;

public class TarUtils_formatUnsignedOctalString_TriageGen2Test {













    @Test
    public void testFormatUnsignedOctalString_LargeValue() {
        // Max value for 8 octal digits is 8^8 - 1 = 16777215
        byte[] buffer = new byte[8];
        long val = 16777215L; 
        TarUtils.formatUnsignedOctalString(val, buffer, 0, 8);
        byte[] expected = "77777777".getBytes();
        assertArrayEquals(expected, buffer);
    }


}

